"""HTTP handlers."""
import json
import logging

log = logging.getLogger(__name__)



def handle_create(request):
    """Create endpoint."""
    log.info("%s", request.get("path"))
    return {"status": 200, "body": json.dumps({"ok": True})}


def handle_get(request):
